window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e1b0410d778089e2"]={"versions": [{"id": "FIG-e1b0410d778089e2", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das Dem-Modul (Diagnostic Event Manager) innerhalb der AUTOSAR Classic Platform. Es definiert die statische Metamodell-Struktur für zählerbasierte Entprellklassen (<code>DemDebounceCounterBasedClass</code>) unterhalb des Konfigurationscontainers <code>DemConfigSet</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Konfigurationsentitäten und Parameter:</p>\n<ul class=\"fig-list\">\n<li><code>DemConfigSet : EcucParamConfContainerDef</code>: Übergeordneter Konfigurationscontainer.</li>\n<li><code>DemDebounceCounterBasedClass : EcucParamConfContainerDef</code>: Sub-Container (Aggregation <code>+subContainer</code>, Multiplizität 0..65535) zur Definition wiederverwendbarer zählerbasierter Entprellalgorithmus-Klassen.</li>\n<li>Enthaltene Parameter (Aggregation <code>+parameter</code>):</li>\n<li><code>DemDebounceCounterIncrementStepSize : EcucIntegerParamDef</code> (min = 1, max = 32767)</li>\n<li><code>DemDebounceCounterDecrementStepSize : EcucIntegerParamDef</code> (min = 1, max = 32768)</li>\n<li><code>DemDebounceCounterFailedThreshold : EcucIntegerParamDef</code> (min = 1, max = 32767)</li>\n<li><code>DemDebounceCounterPassedThreshold : EcucIntegerParamDef</code> (min = -32768, max = -1)</li>\n<li><code>DemDebounceCounterJumpUp : EcucBooleanParamDef</code></li>\n<li><code>DemDebounceCounterJumpDown : EcucBooleanParamDef</code></li>\n<li><code>DemDebounceCounterJumpDownValue : EcucIntegerParamDef</code> (min = -32768, max = 32767, defaultValue = 0)</li>\n<li><code>DemDebounceCounterJumpUpValue : EcucIntegerParamDef</code> (min = -32768, max = 32767, defaultValue = 0)</li>\n<li><code>DemDebounceBehavior : EcucEnumerationParamDef</code> (Multiplizität 1..1) mit den Literalen (<code>+literal</code>):</li>\n<li><code>DEM_DEBOUNCE_FREEZE : EcucEnumerationLiteralDef</code></li>\n<li><code>DEM_DEBOUNCE_RESET : EcucEnumerationLiteralDef</code></li>\n<li><code>DemDebounceCounterStorage : EcucBooleanParamDef</code> (defaultValue = false)</li>\n<li><code>DemCounterBasedFdcThresholdStorageValue : EcucIntegerParamDef</code> (min = 1, max = 32767, Multiplizität 0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Daten-/Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Kontrollflüsse dar. Sie spezifiziert die Parameter zur Laufzeitsteuerung des zählerbasierten Entprellmechanismus im Dem: Inkrementieren bei FAILED-Events, Dekrementieren bei PASSED-Events, Erreichen von Schwellwerten (<code>FailedThreshold</code>, <code>PassedThreshold</code>) zur Qualifikation des Fehlerstatus, Sprungverhalten (<code>JumpUp</code>, <code>JumpDown</code>) mit Zielwerten sowie Einfrieren (<code>FREEZE</code>) oder Zurücksetzen (<code>RESET</code>) des Zählers bei Deaktivierung der Entprellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterstruktur und Dem-Generatoren. Konfiguratoren müssen sicherstellen, dass Wertebereiche eingehalten werden (z. B. negative Werte für <code>PassedThreshold</code>, positive für <code>FailedThreshold</code>). <code>DemDebounceBehavior</code> ist verpflichtend (1..1), während <code>DemCounterBasedFdcThresholdStorageValue</code> optional ist (0..1). Zählerbasierte Entprellklassen können bis zu 65535-mal instanziiert werden.</p>"}, {"id": "FIG-ae4b161fb7e8bc8e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsparametersatzes (ECUC) für das Dem-Modul (Diagnostic Event Manager) innerhalb der AUTOSAR Classic Platform. Es definiert die statische Metamodell-Struktur für zählerbasierte Entprellklassen (<code>DemDebounceCounterBasedClass</code>) unterhalb des Konfigurationscontainers <code>DemConfigSet</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Konfigurationsentitäten und Parameter:</p>\n<ul class=\"fig-list\">\n<li><code>DemConfigSet: EcucParamConfContainerDef</code>: Übergeordneter Konfigurationscontainer.</li>\n<li><code>DemDebounceCounterBasedClass: EcucParamConfContainerDef</code>: Sub-Container (Aggregation <code>+subContainer</code>, Multiplizität 0..65535) zur Definition wiederverwendbarer zählerbasierter Entprellalgorithmus-Klassen.</li>\n<li>Enthaltene Parameter (Aggregation <code>+parameter</code>):</li>\n<li><code>DemDebounceCounterIncrementStepSize: EcucIntegerParamDef</code> (min = 1, max = 32767)</li>\n<li><code>DemDebounceCounterDecrementStepSize: EcucIntegerParamDef</code> (min = 1, max = 32768)</li>\n<li><code>DemDebounceCounterFailedThreshold: EcucIntegerParamDef</code> (min = 1, max = 32767)</li>\n<li><code>DemDebounceCounterPassedThreshold: EcucIntegerParamDef</code> (min = -32768, max = -1)</li>\n<li><code>DemDebounceCounterJumpUp: EcucBooleanParamDef</code></li>\n<li><code>DemDebounceCounterJumpDown: EcucBooleanParamDef</code></li>\n<li><code>DemDebounceCounterJumpDownValue: EcucIntegerParamDef</code> (min = -32768, max = 32767, defaultValue = 0)</li>\n<li><code>DemDebounceCounterJumpUpValue: EcucIntegerParamDef</code> (min = -32768, max = 32767, defaultValue = 0)</li>\n<li><code>DemDebounceBehavior: EcucEnumerationParamDef</code> (Multiplizität 1..1) mit den Literalen (<code>+literal</code>):</li>\n<li><code>DEM_DEBOUNCE_FREEZE: EcucEnumerationLiteralDef</code></li>\n<li><code>DEM_DEBOUNCE_RESET: EcucEnumerationLiteralDef</code></li>\n<li><code>DemDebounceCounterStorage: EcucBooleanParamDef</code> (defaultValue = false)</li>\n<li><code>DemCounterBasedFdcThresholdStorageValue: EcucIntegerParamDef</code> (min = 1, max = 32767, Multiplizität 0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches Daten-/Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Interaktionen oder Kontrollflüsse dar. Sie spezifiziert die Parameter zur Laufzeitsteuerung des zählerbasierten Entprellmechanismus im Dem: Inkrementieren bei FAILED-Events, Dekrementieren bei PASSED-Events, Erreichen von Schwellwerten (<code>FailedThreshold</code>, <code>PassedThreshold</code>) zur Qualifikation des Fehlerstatus, Sprungverhalten (<code>JumpUp</code>, <code>JumpDown</code>) mit Zielwerten sowie Einfrieren (<code>FREEZE</code>) oder Zurücksetzen (<code>RESET</code>) des Zählers bei Deaktivierung der Entprellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für die ECUC-Parameterstruktur und Dem-Generatoren. Konfiguratoren müssen sicherstellen, dass Wertebereiche eingehalten werden (z. B. negative Werte für <code>PassedThreshold</code>, positive für <code>FailedThreshold</code>). <code>DemDebounceBehavior</code> ist verpflichtend (1..1), während <code>DemCounterBasedFdcThresholdStorageValue</code> optional ist (0..1). Zählerbasierte Entprellklassen können bis zu 65535-mal instanziiert werden.</p>"}], "trans": [{"from": "FIG-e1b0410d778089e2", "to": "FIG-ae4b161fb7e8bc8e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>In allen Klassennamen und Literalen wurde das Leerzeichen vor dem Doppelpunkt entfernt (z. B. <code>DemConfigSet :</code> zu <code>DemConfigSet:</code>, <code>DemDebounceCounterBasedClass :</code> zu <code>DemDebounceCounterBasedClass:</code> sowie bei allen Parametern und Enumeration-Literals).</li>\n</ul>"}]};
